const API_BASE = import.meta.env.VITE_API_BASE || '';
function readCookie(name) {
  const entry = document.cookie.split('; ').find((x) => x.startsWith(`${name}=`));
  return entry ? decodeURIComponent(entry.split('=').slice(1).join('=')) : '';
}
async function api(path, options = {}) {
  const method = options.method || 'GET';
  const headers = new Headers(options.headers || {});
  if (options.body && !(options.body instanceof FormData)) headers.set('Content-Type', 'application/json');
  if (!['GET', 'HEAD', 'OPTIONS'].includes(method)) headers.set('X-CSRF-Token', readCookie('v404_csrf'));
  const response = await fetch(`${API_BASE}${path}`, { credentials: 'include', ...options, method, headers });
  const contentType = response.headers.get('content-type') || '';
  const data = contentType.includes('application/json') ? await response.json() : await response.text();
  if (!response.ok) throw new Error(data?.detail || data?.message || `Request failed (${response.status})`);
  return data;
}
const fmt = (v) => typeof v === 'number' ? new Intl.NumberFormat('en-IN').format(v) : (v ?? '—');
const shortDate = (v) => v ? String(v).replace('T', ' ').replace('Z', ' UTC').slice(0, 19) : '—';
const safeJson = (v) => typeof v === 'string' ? v : JSON.stringify(v ?? {}, null, 2);

