function Button({ children, onClick, variant = 'secondary', size = '', disabled = false, icon: Icon }) {
  return <button className={`btn ${variant} ${size}`} onClick={onClick} disabled={disabled}>{Icon && <Icon size={15}/>}<span>{children}</span></button>;
}
function Pill({ children, tone = 'neutral' }) { return <span className={`pill ${tone}`}>{children}</span>; }
function Panel({ title, sub, action, children, className = '' }) {
  return <section className={`panel ${className}`}><div className="panel-head"><div>{title && <h3>{title}</h3>}{sub && <p>{sub}</p>}</div>{action}</div>{children}</section>;
}
function Metric({ label, value, note, icon: Icon, tone = 'blue', trend }) {
  return <div className="metric"><div className={`metric-icon ${tone}`}><Icon size={18}/></div><div className="metric-copy"><span>{label}</span><strong>{fmt(value)}</strong><small>{note}</small></div>{trend && <div className="metric-trend">{trend}</div>}</div>;
}
function Empty({ title = 'Nothing to show', detail = 'There are no records in this view yet.' }) {
  return <div className="empty"><div className="empty-icon"><Database size={20}/></div><b>{title}</b><span>{detail}</span></div>;
}
function Table({ columns, rows, emptyText = 'No records found', rowKey }) {
  if (!rows?.length) return <Empty title={emptyText}/>;
  return <div className="table-wrap"><table><thead><tr>{columns.map((c) => <th key={c.key}>{c.label}</th>)}</tr></thead><tbody>{rows.map((r, i) => <tr key={rowKey ? r[rowKey] : i}>{columns.map((c) => <td key={c.key}>{c.render ? c.render(r) : (r[c.key] ?? '—')}</td>)}</tr>)}</tbody></table></div>;
}
function Loading() { return <div className="loading"><div className="spinner"/>Loading workspace data…</div>; }
function ErrorLine({ children }) { return children ? <div className="error-line"><AlertCircle size={15}/>{children}</div> : null; }
function Toast({ toast, onClose }) {
  useEffect(() => { if (!toast) return; const t = setTimeout(onClose, 5200); return () => clearTimeout(t); }, [toast, onClose]);
  if (!toast) return null;
  return <div className={`toast ${toast.type || 'success'}`}><span>{toast.type === 'error' ? <AlertCircle size={17}/> : <CheckCircle2 size={17}/>}</span><div><b>{toast.title || (toast.type === 'error' ? 'Action failed' : 'Completed')}</b><p>{toast.message}</p></div><button onClick={onClose}><X size={15}/></button></div>;
}
function Field({ label, value, onChange, placeholder, type = 'text', required = false, options, multiline = false }) {
  return <label className="field"><span>{label}</span>{options ? <select value={value} onChange={(e) => onChange(e.target.value)}>{options.map((o) => <option key={o.value ?? o} value={o.value ?? o}>{o.label ?? o}</option>)}</select> : multiline ? <textarea value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} required={required}/> : <input type={type} value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} required={required}/>}</label>;
}
function Modal({ title, onClose, onSubmit, children, submitLabel = 'Confirm', busy = false, danger = false }) {
  return <div className="modal-backdrop" onMouseDown={(e) => e.target === e.currentTarget && onClose()}><div className="modal"><div className="modal-head"><div><h3>{title}</h3><p>All control changes in this build are recorded as simulations.</p></div><button className="icon-btn" onClick={onClose}><X size={18}/></button></div><div className="modal-content">{children}</div><div className="modal-foot"><Button onClick={onClose}>Cancel</Button><Button variant={danger ? 'danger' : 'primary'} onClick={onSubmit} disabled={busy}>{busy ? 'Saving…' : submitLabel}</Button></div></div></div>;
}
function SectionIntro({ title, children, right }) { return <div className="section-intro"><div><h2>{title}</h2><p>{children}</p></div>{right}</div>; }

function Login({ onLogin }) {
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(e) { e.preventDefault(); setBusy(true); setError(''); try { await onLogin(email, password); } catch (err) { setError(err.message); } finally { setBusy(false); } }
  return <div className="login-screen"><div className="login-side"><div className="login-brand"><div className="brand-mark"><Shield size={23}/></div><span>VARIANT<span className="brand-accent">404</span></span></div><div className="login-message"><Pill tone="green">CONTROL ASSURANCE PLATFORM</Pill><h1>Security signals.<br/><em>Accountable</em> action.</h1><p>Bring investigation evidence, API activity and remediation workflows into one operational workspace.</p><div className="login-proof"><div><Activity size={17}/><span>API anomaly monitoring</span></div><div><ShieldCheck size={17}/><span>Verified control workflows</span></div><div><FileCheck2 size={17}/><span>Evidence-backed assurance</span></div></div></div><div className="login-foot">CRIMEATHON’26 · CASE CR-26-047 · SIMULATION ENVIRONMENT</div></div><div className="login-main"><div className="login-card"><div className="mobile-brand"><Shield size={21}/> VARIANT404</div><span className="eyebrow">SECURE WORKSPACE</span><h2>Welcome back</h2><p>Sign in to access your control centre.</p><form onSubmit={submit}><Field label="Work email" value={email} onChange={setEmail} type="email" placeholder="you@company.com" required/><Field label="Password" value={password} onChange={setPassword} type="password" placeholder="Enter your password" required/><ErrorLine>{error}</ErrorLine><button className="btn primary login-btn" disabled={busy}>{busy ? 'Authenticating…' : 'Sign in'} <ArrowUpRight size={16}/></button></form><div className="login-secure"><LockKeyhole size={14}/> Protected with secure, HTTP-only sessions</div><div className="login-note">Access is provisioned by your workspace administrator.</div></div><div className="login-copyright">© 2026 Variant404 · Security assurance workspace</div></div></div>;
}

