 return <><SectionIntro title="Audit & Risk">Turn findings into owned tasks, preserve open/closed status and require a reference before a task can be marked complete.</SectionIntro><div className="metrics-grid compact"><Metric label="Open audit findings" value={data.findings.filter(f=>f.status==='Open').length} note="E11 report snapshot" icon={FileCheck2} tone="amber"/><Metric label="Overdue risk reviews" value={data.risks.filter(r=>r.overdue).length} note="As at E09 export date" icon={Clock3} tone="red"/><Metric label="Remediation tasks" value={data.tasks.length} note="Seeded from audit and risk records" icon={TicketCheck}/><Metric label="Closed with evidence" value={data.tasks.filter(t=>t.status.startsWith('CLOSED')).length} note="Evidence reference recorded" icon={BadgeCheck} tone="green"/></div><Panel title="Internal audit findings" sub="E11 is a September 2025 snapshot; the March 2026 follow-up result is not present."><Table rows={data.findings} columns={[{key:'finding',label:'#'},{key:'title',label:'Finding'},{key:'rating',label:'Rating',render:r=><Pill tone={r.rating==='High'?'red':r.rating==='Medium'?'amber':'neutral'}>{r.rating}</Pill>},{key:'status',label:'E11 status',render:r=><Pill tone={r.status==='Open'?'amber':'green'}>{r.status}</Pill>},{key:'due',label:'Due'},{key:'followup_status',label:'Follow-up'},{key:'action',label:'Recommended action'}]}/></Panel><Panel title="Risk register" sub="Overdue status is calculated against the E09 export date (2 September 2026)."><Table rows={data.risks} columns={[{key:'risk_id',label:'Risk ID',render:r=><b>{r.risk_id}</b>},{key:'title',label:'Risk'},{key:'owner',label:'Owner'},{key:'score',label:'Score'},{key:'rating',label:'Rating',render:r=><Pill tone={r.rating==='High'?'red':r.rating==='Medium'?'amber':'neutral'}>{r.rating}</Pill>},{key:'status',label:'Status'},{key:'next_review_due',label:'Next review'},{key:'overdue',label:'Review status',render:r=><Pill tone={r.overdue?'red':'green'}>{r.overdue?'Overdue':'On schedule'}</Pill>} ]}/></Panel><Panel title="Remediation task queue" sub="Closing a task records a reference; it does not independently validate the referenced evidence."><Table rows={data.tasks} rowKey="task_id" columns={[{key:'task_id',label:'Task ID',render:r=><b className="mono">{r.task_id}</b>},{key:'category',label:'Category'},{key:'title',label:'Task'},{key:'owner',label:'Owner'},{key:'due_date',label:'Due'},{key:'status',label:'Status',render:r=><Pill tone={r.status.startsWith('CLOSED')?'green':'amber'}>{r.status}</Pill>},{key:'evidence',label:'Evidence reference'},{key:'action',label:'Action',render:r=>!r.status.startsWith('CLOSED')&&<Button size="sm" onClick={()=>closeTask(r)}>Add closure evidence</Button>} ]}/></Panel></>;
