 async function verify(){setBusy(true);try{const r=await api('/api/action-ledger/verify',{method:'POST'});setToast({message:r.message,type:r.valid?'success':'error'});load()}catch(e){setToast({type:'error',message:e.message})}finally{setBusy(false)}}
 return <><SectionIntro title="Evidence Vault">Preserve original evidence with SHA-256 file hashes and verify the append-only, hash-linked action ledger.</SectionIntro><div className="metrics-grid compact"><Metric label="Evidence files" value={data.files.length} note="Original supplied E01–E20" icon={HardDrive}/><Metric label="Evidence integrity" value="Read-only" note="Source package preserved" icon={ShieldCheck} tone="green"/><Metric label="Action ledger" value={data.action_chain.valid?'Valid':'Mismatch'} note={data.action_chain.message} icon={FileCheck2} tone={data.action_chain.valid?'green':'red'}/><Metric label="Recent actions" value={data.actions.length} note="Latest 100 events" icon={Activity} tone="violet"/></div><Panel title="Evidence manifest" sub="Hash the supplied files to create a reproducible integrity manifest." action={<Button variant="primary" onClick={manifest} disabled={busy} icon={FileJson}>{busy?'Working…':'Create SHA-256 manifest'}</Button>}><Table rows={data.files} columns={[{key:'file',label:'Evidence file',render:r=><b>{r.file}</b>},{key:'bytes',label:'Size',render:r=>`${(r.bytes/1024).toFixed(1)} KB`},{key:'sha256',label:'SHA-256',render:r=><span className="mono hash-value">{r.sha256}</span>} ]}/></Panel><Panel title="Tamper-evident action ledger" sub="Each action includes the previous hash, linking the event sequence together." action={<Button onClick={verify} disabled={busy} icon={RefreshCw}>Verify chain</Button>}><div className={`chain-status ${data.action_chain.valid?'valid':'invalid'}`}><ShieldCheck size={19}/><div><b>{data.action_chain.message}</b><span>{data.action_chain.valid?'No mismatch was detected in the current sequence.':'A mismatch was found; preserve the database and investigate.'}</span></div></div><Table rows={data.actions} columns={[{key:'seq',label:'#'},{key:'ts_utc',label:'Timestamp',render:r=>shortDate(r.ts_utc)},{key:'actor',label:'Actor'},{key:'action',label:'Action',render:r=><b>{r.action}</b>},{key:'object_ref',label:'Object'},{key:'event_hash',label:'Event hash',render:r=><span className="mono hash-value">{r.event_hash?.slice(0,24)}…</span>} ]}/></Panel></>;
