function CompanyModule({setToast}) {
 const [data,setData]=useState(null);const [file,setFile]=useState(null);const [mapping,setMapping]=useState(null);const [busy,setBusy]=useState(false);const load=useCallback(async()=>{try{setData(await api('/api/company'))}catch(e){setToast({type:'error',message:e.message})}},[setToast]);useEffect(()=>{load()},[load]);
 async function upload(e){e.preventDefault();if(!file)return;setBusy(true);try{const form=new FormData();form.append('file',file);if(mapping)form.append('mapping',mapping);const r=await api('/api/company/import',{method:'POST',body:form});setToast({message:`Imported ${r.count} records. ${r.message}`});setFile(null);setMapping(null);load()}catch(e){setToast({type:'error',message:e.message})}finally{setBusy(false)}}
 if(!data)return <Loading/>;
 return <><SectionIntro title="Company Workspace">Bring your own CSV audit events into the normalized workspace using a documented field map. Imported timestamps are not assumed to be UTC unless the source includes an offset.</SectionIntro><div className="two-col"><Panel title="Import company events" sub="CSV only · 15 MB max · UTF-8 supported"><form onSubmit={upload} className="stack-form"><label className="upload-box"><FileSpreadsheet size={22}/><b>{file?.name || 'Choose an events CSV'}</b><span>{file?`${(file.size/1024).toFixed(1)} KB selected`:'Drop file here or browse from your device'}</span><input type="file" accept=".csv,text/csv" onChange={e=>setFile(e.target.files?.[0]||null)}/></label><label className="field"><span>Optional JSON field mapping</span><input type="file" accept=".json,application/json" onChange={e=>setMapping(e.target.files?.[0]||null)}/></label><div className="mapping-help"><b>Supported normalized columns</b><code>timestamp · event_id · system · actor · action · object_id · source_ip · result · approval_ref · request_id</code><a href={data.template}>Download sample CSV</a> <a href={data.mapping}>Download field map</a></div><Button variant="primary" disabled={!file||busy} icon={ArrowUpRight}>{busy?'Importing…':'Import events'}</Button></form></Panel><Panel title="Import safety rules" sub="Review before interpreting imported events"><div className="rule-list"><div><CheckCircle2 size={16}/><span>Original CSV is processed as data; uploaded files are not executed.</span></div><div><CheckCircle2 size={16}/><span>Field mappings are validated as JSON objects.</span></div><div><AlertTriangle size={16}/><span>Naive timestamps remain timezone-unverified and are not coerced to UTC.</span></div><div><LockKeyhole size={16}/><span>Only authenticated workspace users can import new data.</span></div></div></Panel></div><Panel title="Imported company events" sub={`${fmt(data.total)} record(s) currently stored; latest 250 shown.`}><Table rows={data.rows} columns={[{key:'ts_utc',label:'Normalized UTC',render:r=>r.ts_utc?shortDate(r.ts_utc):<Pill tone="amber">Unverified</Pill>},{key:'system',label:'System'},{key:'actor',label:'Actor'},{key:'action',label:'Action'},{key:'object_id',label:'Object'},{key:'source_ip',label:'Source IP'},{key:'result',label:'Result'},{key:'time_reliability',label:'Time quality',render:r=><Pill tone={r.ts_utc?'green':'amber'}>{r.time_reliability}</Pill>} ]}/></Panel></>;
}

function ScenarioModule({setToast}) {
 const [form,setForm]=useState({change_id:'SCENARIO-UNSEEN-01',vendor_id:'V-TEST-08',vendor_name:'New variation supplier',changed_by:'key-tb-07',field:'bank_account',approval_ref:'',source_ip:'198.51.100.24',request_id:'',ts_utc:'2026-09-07T10:00:00Z'});const [result,setResult]=useState(null);const [busy,setBusy]=useState(false);
 async function evaluate(e){e.preventDefault();setBusy(true);try{const r=await api('/api/scenario/evaluate',{method:'POST',body:JSON.stringify(form)});setResult(r.result);setToast({message:'Scenario evaluated without modifying evidence or payment state.'})}catch(e){setToast({type:'error',message:e.message})}finally{setBusy(false)}}
 const set=(k,v)=>setForm(s=>({...s,[k]:v}));
 return <><SectionIntro title="Scenario Lab">Evaluate a hidden-style variation against the per-credential host baseline and approval interlock. The scenario never writes to source evidence.</SectionIntro><div className="two-col scenario-grid"><Panel title="Scenario input" sub="Change any field to test how the control adapts."><form className="stack-form" onSubmit={evaluate}><div className="form-two"><Field label="Scenario ID" value={form.change_id} onChange={v=>set('change_id',v)}/><Field label="Vendor ID" value={form.vendor_id} onChange={v=>set('vendor_id',v)}/></div><Field label="Vendor name" value={form.vendor_name} onChange={v=>set('vendor_name',v)}/><div className="form-two"><Field label="Actor / API credential" value={form.changed_by} onChange={v=>set('changed_by',v)}/><Field label="Field changed" value={form.field} onChange={v=>set('field',v)} options={['bank_account','contact_email','address','tax_id'].map(x=>({label:x,value:x}))}/></div><div className="form-two"><Field label="Source IP" value={form.source_ip} onChange={v=>set('source_ip',v)}/><Field label="Approval reference" value={form.approval_ref} onChange={v=>set('approval_ref',v)} placeholder="Leave blank to test the approval gate"/></div><Field label="Request ID (optional correlation)" value={form.request_id} onChange={v=>set('request_id',v)}/><Field label="Timestamp (UTC)" value={form.ts_utc} onChange={v=>set('ts_utc',v)}/><Button variant="primary" disabled={busy} icon={Zap}>{busy?'Evaluating…':'Evaluate scenario'}</Button></form></Panel><Panel title="Control decision" sub="Evaluation output and reason codes.">{result?<div className="scenario-result"><div className={`decision-banner ${result.hold_required?'held':'clear'}`}><div>{result.hold_required?<ShieldAlert size={23}/>:<ShieldCheck size={23}/>}</div><div><span>POLICY DECISION</span><b>{result.hold_required?'HOLD REQUIRED':'NO HOLD REQUIRED'}</b><small>Risk score: {result.risk_score} · threshold: {result.threshold_crossed?'crossed':'not crossed'}</small></div></div><div className="decision-reasons"><b>Score reasoning</b>{result.risk_reasons?.map((x,i)=><div key={i}><CheckCircle2 size={15}/>{x}</div>)}{!result.risk_reasons?.length&&<p>No risk points were applied by the selected rules.</p>}</div><div className="decision-facts"><div><span>Host baseline</span><b>{result.baseline_mature?'Established':'Insufficient history'}</b></div><div><span>Trusted hosts</span><b>{result.trusted_hosts?.join(', ')||'Not established'}</b></div><div><span>Exact API join</span><b>{result.exact_api_join?'Confirmed':'Not confirmed'}</b></div></div><p className="modal-note">{result.status}. This is a case-calibrated heuristic, not proof of malicious intent.</p></div>:<Empty title="No scenario evaluated" detail="Enter a new variation and run the control to see the policy decision."/>}</Panel></div><div className="scope-note"><CircleHelp size={15}/> The five-percent host baseline and score threshold were tuned to the supplied dataset. Validate independently before production use.</div></>;
}

function BriefModule({setToast}) {
 const [preview,setPreview]=useState('');const [busy,setBusy]=useState(false);
 async function generate(){setBusy(true);try{const r=await api('/api/brief/generate',{method:'POST'});setPreview(r.preview);setToast({message:'Weekly assurance brief generated.'})}catch(e){setToast({type:'error',message:e.message})}finally{setBusy(false)}}
 return <><SectionIntro title="Weekly Assurance Brief">Create a concise control update for management and the Audit Committee using current workflow state and the supplied evidence limitations.</SectionIntro><Panel title="Management reporting" sub="The report explicitly distinguishes the synthetic case evidence from simulated control actions." action={<Button variant="primary" onClick={generate} disabled={busy} icon={FileText}>{busy?'Generating…':'Generate weekly brief'}</Button>}><div className="brief-preview"><div className="brief-icon"><FileText size={24}/></div><div><b>Weekly Security Control Assurance Brief</b><p>Prepared for the General Manager and Audit Committee Chair. Includes payment holds, offboarding, integration gaps, audit findings, overdue risk reviews, notice routing and export history.</p>{preview&&<a href="/api/downloads/weekly_security_assurance_brief.txt" className="download-link"><Download size={15}/> Download generated TXT</a>}</div></div>{preview&&<pre className="brief-text">{preview}</pre>}</Panel><div className="info-strip"><AlertCircle size={17}/><div><b>Reporting caveat</b><span>The brief is a snapshot of the data and workflow state available at generation time. It does not assert that simulated actions were performed on a live system or that the E11 follow-up result is known.</span></div></div></>;
}

function PasswordModal({ onClose, onSaved, setToast }) {
 const [current,setCurrent]=useState(''); const [next,setNext]=useState(''); const [confirm,setConfirm]=useState(''); const [busy,setBusy]=useState(false);
 async function submit(){if(next.length<12){setToast({type:'error',message:'New password must be at least 12 characters.'});return}if(next!==confirm){setToast({type:'error',message:'The new password and confirmation do not match.'});return}setBusy(true);try{const r=await api('/api/auth/change-password',{method:'POST',body:JSON.stringify({current_password:current,new_password:next})});setToast({message:r.message});onSaved()}catch(e){setToast({type:'error',message:e.message})}finally{setBusy(false)}}
 return <Modal title="Change your password" onClose={onClose} onSubmit={submit} submitLabel="Update password" busy={busy}><Field label="Current password" value={current} onChange={setCurrent} type="password"/><Field label="New password (12+ characters)" value={next} onChange={setNext} type="password"/><Field label="Confirm new password" value={confirm} onChange={setConfirm} type="password"/><p className="modal-note">Your session will end after the password is updated. Sign in again using the new password.</p></Modal>;
}

function UsersModule({setToast}) {
 const [rows,setRows]=useState(null);const [form,setForm]=useState({email:'',display_name:'',password:'',role:'analyst'});const [busy,setBusy]=useState(false);
 const load=useCallback(async()=>{try{setRows((await api('/api/users')).users)}catch(e){setToast({type:'error',message:e.message})}},[setToast]);useEffect(()=>{load()},[load]);
 async function create(e){e.preventDefault();setBusy(true);try{await api('/api/users',{method:'POST',body:JSON.stringify(form)});setToast({message:'Workspace account created.'});setForm({email:'',display_name:'',password:'',role:'analyst'});load()}catch(e){setToast({type:'error',message:e.message})}finally{setBusy(false)}}
 if(!rows)return <Loading/>;
 return <><SectionIntro title="Workspace access">Provision named accounts and assign roles. Shared or default passwords should not be used.</SectionIntro><div className="two-col"><Panel title="Create a team account"><form className="stack-form" onSubmit={create}><Field label="Display name" value={form.display_name} onChange={v=>setForm({...form,display_name:v})}/><Field label="Email" type="email" value={form.email} onChange={v=>setForm({...form,email:v})}/><Field label="Temporary password (12+ characters)" type="password" value={form.password} onChange={v=>setForm({...form,password:v})}/><Field label="Role" value={form.role} onChange={v=>setForm({...form,role:v})} options={[{label:'Analyst — review and standard workflows',value:'analyst'},{label:'Approver — sensitive simulated actions',value:'approver'},{label:'Administrator — manage access',value:'admin'}]}/><Button variant="primary" disabled={busy}>{busy?'Creating…':'Create account'}</Button></form></Panel><Panel title="Role permissions"><div className="rule-list"><div><UserRound size={16}/><span><b>Analyst</b> — view evidence and run standard analysis workflows.</span></div><div><BadgeCheck size={16}/><span><b>Approver</b> — release simulated payment holds, rotate credentials and approve exports.</span></div><div><UserCog size={16}/><span><b>Administrator</b> — all controls plus workspace account provisioning.</span></div></div></Panel></div><Panel title="Workspace accounts"><Table rows={rows} columns={[{key:'display_name',label:'Name'},{key:'email',label:'Email'},{key:'role',label:'Role',render:r=><Pill tone={r.role==='admin'?'violet':r.role==='approver'?'blue':'neutral'}>{r.role}</Pill>},{key:'is_active',label:'Status',render:r=><Pill tone={r.is_active?'green':'red'}>{r.is_active?'Active':'Disabled'}</Pill>},{key:'last_login',label:'Last sign-in',render:r=>shortDate(r.last_login)}]}/></Panel></>;
}

function Content({active,toast,setToast,search,onNavigate}) {
 switch(active){
  case 'Overview': return <Overview data={toast.overview} onNavigate={onNavigate}/>;
  case 'API Monitor': return <ApiMonitor setToast={setToast} search={search}/>;
  case 'Payment Interlock': return <PaymentModule setToast={setToast}/>;
  case 'Identity Lifecycle': return <IdentityModule setToast={setToast}/>;
  case 'Integration Security': return <IntegrationModule setToast={setToast}/>;
  case 'Export Controls': return <ExportsModule setToast={setToast}/>;
  case 'Sensitive Data': return <SensitiveModule setToast={setToast}/>;
  case 'Time Integrity': return <TimeModule setToast={setToast}/>;
  case 'Vendor & Notices': return <NoticesModule setToast={setToast}/>;
  case 'Audit & Risk': return <GovernanceModule setToast={setToast}/>;
  case 'Evidence Vault': return <EvidenceModule setToast={setToast}/>;
  case 'Company Workspace': return <CompanyModule setToast={setToast}/>;
  case 'Scenario Lab': return <ScenarioModule setToast={setToast}/>;
  case 'Weekly Brief': return <BriefModule setToast={setToast}/>;
  case 'Workspace Access': return <UsersModule setToast={setToast}/>;
  default: return <Overview data={toast.overview} onNavigate={onNavigate}/>;
 }
}

function App() {
 const [user,setUser]=useState(null);const [checking,setChecking]=useState(true);const [active,setActive]=useState('Overview');const [mobileOpen,setMobileOpen]=useState(false);const [toast,setToastState]=useState(null);const [search,setSearch]=useState('');const [overview,setOverview]=useState(null);const [overviewLoading,setOverviewLoading]=useState(false);const [accountOpen,setAccountOpen]=useState(false);
 const setToast=useCallback((v)=>setToastState(v),[]);const clearToast=useCallback(()=>setToastState(null),[]);
 const loadOverview=useCallback(async()=>{if(!user)return;setOverviewLoading(true);try{setOverview(await api('/api/overview'))}catch(e){setToast({type:'error',message:e.message})}finally{setOverviewLoading(false)}},[user,setToast]);
 useEffect(()=>{api('/api/auth/me').then(r=>setUser(r.user)).catch(()=>setUser(null)).finally(()=>setChecking(false))},[]);
 useEffect(()=>{if(user)loadOverview()},[user,loadOverview]);
 async function signIn(email,password){await api('/api/auth/login',{method:'POST',body:JSON.stringify({email,password})});const r=await api('/api/auth/me');setUser(r.user);setActive('Overview');}
 async function signOut(){try{await api('/api/auth/logout',{method:'POST'})}catch{}setUser(null);setOverview(null);}
 function navigate(item){if(item==='Sign out'){signOut();return}setActive(item);setSearch('');if(item==='Overview')loadOverview()}
 if(checking)return <div className="app-loading"><div className="spinner"/><span>Loading secure workspace…</span></div>;
 if(!user)return <Login onLogin={signIn}/>;
 const activeDesc=descriptions[active] || 'Manage authorized workspace access.';
 return <div className="app-shell"><Sidebar active={active} onNavigate={navigate} user={user} mobileOpen={mobileOpen} onClose={()=>setMobileOpen(false)}/><main className="main-area"><Topbar user={user} active={active} onSearch={setSearch} onLogout={signOut} onChangePassword={()=>setAccountOpen(true)} onToggleMenu={()=>setMobileOpen(v=>!v)}/><div className="page-wrap"><div className="page-heading"><div><div className="eyebrow">VARIANT404 / CONTROL CENTRE</div><h1>{active}</h1><p>{activeDesc}</p></div><div className="heading-right"><div className="secure-indicator"><span/><div><b>Secure session</b><small>Authenticated · {user.role}</small></div></div><button className="icon-btn refresh-btn" title="Refresh overview" onClick={loadOverview}><RefreshCw size={17}/></button>{user.role==='admin'&&<Button size="sm" onClick={()=>navigate('Workspace Access')} icon={Users}>Manage access</Button>}</div></div>{active==='Overview'&&overviewLoading&&!overview?<Loading/>:<Content active={active} toast={{overview}} setToast={setToast} search={search} onNavigate={navigate}/>}<footer className="page-footer"><span>VARIANT404 · VERSION 2.0.0</span><span><ShieldCheck size={13}/> Synthetic case data · Simulated control actions · Hosted-ready</span><span>CR-26-047</span></footer></div></main>{accountOpen&&<PasswordModal onClose={()=>setAccountOpen(false)} setToast={setToast} onSaved={()=>{setAccountOpen(false);setUser(null);setOverview(null)}}/>}<Toast toast={toast} onClose={clearToast}/></div>;
}

createRoot(document.getElementById('root')).render(<React.StrictMode><App/></React.StrictMode>);
